import {createErrorScene} from './spatial-error-gm-oracle';
import {createNearestNeighborScene} from './spatial-regression-diagnostics-oracle';
import {createLagScene} from './spatial-two-stage-least-squares-oracle';

/**
 * spreg ML_Lag / ML_Error reference pins (spreg 1.9.1, libpysal 4.15.0, numpy 2.5.4, scipy 1.18.1; float64),
 * generated by `fix/work/C/U5/pin-ml-spreg.py` + `emit-ml-reference.py` on scenes dumped by
 * `fix/work/C/U5/dump-ml-scenes.ts`: `spreg.ML_Lag(y, X, w, method='full', spat_impacts='full')` and
 * `spreg.ML_Error(y, X, w, method='full')`, weights passed untransformed (transform "O").
 * Coefficient arrays hold the intercept, the predictors, then `rho` / `lambda` last (spreg order);
 * standard errors are the `vm` diagonal, z = estimate / se, p two-sided normal. spreg minimizes the
 * negative concentrated log-likelihood with scipy `minimize_scalar` (bounded, xatol 1e-7), so its
 * `rho` / `lambda` agree with the exact maximizer to about 1e-7: compare them at 1e-5.
 * `specK` is the `k` of spreg's AIC and Schwarz: 4 = intercept + 2 predictors + rho for the lag
 * model, but only intercept + predictors for the error model (`ML_Error` does not count lambda).
 * `conditioning`: numpy float64 Belsley condition number of the raw design (lag: [1, X]; error: the
 * raw filtered [c, X - lambda W X] at the estimate), correlation condition number and largest
 * predictor VIF of the centered design (error: filtered constant c plus filtered centered X).
 * `impacts` (lag): spreg `spmultiplier(w, rho, 'full')` multipliers (direct, indirect, total) and
 * the per-predictor products with the betas.
 * `traces` (lag): numpy tr1, tr2, tr3 of W (I - rho W)^-1 at spreg's rho.
 */
export type SpatialMaximumLikelihoodFixture = {
  rowSumNorm: number;
  betas: number[];
  parameter: number;
  standardErrors: number[];
  z: number[];
  p: number[];
  sigma2: number;
  logLikelihood: number;
  aic: number;
  schwarz: number;
  pseudoRSquared: number;
  specK: number;
  conditioning: {
    conditionNumber: number;
    correlationConditionNumber: number;
    maximumVarianceInflationFactor: number;
  };
};

export type SpatialLagMaximumLikelihoodFixture = SpatialMaximumLikelihoodFixture & {
  pseudoRSquaredSpatial: number;
  traces: [number, number, number];
  impacts: {multipliers: [number, number, number]; values: [number, number, number][]};
};

/** Scene factories of the pinned fixtures (the generators the oracle JSON was dumped from). */
